  rmrep st m -> meta_slot st g ->
  munch [(conc st g, conc st g + META_SIZE)] m m' -> wmono psegs m m' ->
  rw_cells psegs m' (conc st g) (meta_cells st mr') ->
  rmrep (put_meta g mr' st) m'.
Proof.
